import React, { useState, useEffect } from "react";
import { Container, Row, Col } from "react-bootstrap";
import Button from "react-bootstrap/Button";

import "react-pdf/dist/esm/Page/AnnotationLayer.css";

function CommonGround() {
  const [width, setWidth] = useState(1200);

  useEffect(() => {
    setWidth(window.innerWidth);
  }, []);

  return (
    <div>
      <Container fluid className="resume-section" 
      style={{ paddingLeft: 100, paddingRight: 100 }}>
      <Row className="d-flex justify-content-center">
      <Col style={{ maxWidth: "1100px"}}>

      
        <h1 style={{ paddingBottom: 15 }} className="heading">
          <strong>Common Ground</strong>
        </h1>
        <h2 style={{ paddingBottom: 15 }} className="subheading">
          Data-Driven Design
        </h2>
        <p className="subsubheading" style={{ paddingBottom: 15 }}>
            23 Spring, Rhode Island School of Design.
        </p>

        <img src="/Assets/ProjectPages/interior.png" className="img-fluid" style={{paddingBottom: 30}}/>

      <p className="project-description" style={{ paddingBottom: 15 }}>
      What can we do as Somerville rapidly gentrifies? As a class, we engaged 10+ stakeholders on the Gilman Square site to discuss the wants and needs of the local community. I developed visualizations of this valuable conversation data using D3.js to inform the design of a new community center. Let's imagine if we could turn Gilman Square into a central point of connection – a place where Somerville residents can unite, support each other, and access essential resources. Imagine it to be a multi-resource, multilingual community center, a hub that empowers through connection, a space for tenant organizing and a physical anchor for information transparency.
        </p>
      
        <img src="/Assets/ProjectPages/Portfolio_Copy.png" className="img-fluid" style={{paddingBottom: 15}}/>
        <img src="/Assets/ProjectPages/Portfolio_Copy2.png" className="img-fluid" style={{paddingBottom: 15}}/>
        <img src="/Assets/ProjectPages/Portfolio_Copy3.png" className="img-fluid" style={{paddingBottom: 15}}/>
        <img src="/Assets/ProjectPages/exterior.png" className="img-fluid" style={{paddingBottom: 15}}/>
        <img src="/Assets/ProjectPages/snippets.png" className="img-fluid" style={{paddingBottom: 15}}/>


      </Col>
      </Row>
      
      </Container>
    </div>
  );
}

export default CommonGround;
