import React, { useState, useEffect, useRef } from "react";
import { motion, useScroll, useTransform, useSpring } from "framer-motion";
import "./ScrollRevealSlides.css";

const ScrollRevealSlides = ({ slides }) => {
  const containerRef = useRef(null);
  const [activeSlide, setActiveSlide] = useState(0);
  
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start start", "end end"]
  });

  const scaleX = useSpring(scrollYProgress, {
    stiffness: 100,
    damping: 30,
    restDelta: 0.001
  });

  return (
    <div ref={containerRef} className="scroll-reveal-container">
      {/* Progress bar */}
      <motion.div 
        className="slides-progress-bar"
        style={{ scaleX }}
      />
      
      {/* Slide counter */}
      <motion.div 
        className="slide-counter"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 0.5 }}
      >
        <span className="current-slide">{String(activeSlide + 1).padStart(2, '0')}</span>
        <span className="slide-separator">/</span>
        <span className="total-slides">{String(slides.length).padStart(2, '0')}</span>
      </motion.div>

      {slides.map((slide, index) => (
        <SlideSection
          key={index}
          slide={slide}
          index={index}
          noFadeIn={index <= 1}
          noFadeOut={index >= slides.length - 3}
          onVisible={() => setActiveSlide(index)}
        />
      ))}
    </div>
  );
};

const SlideSection = ({ slide, index, noFadeIn, noFadeOut, onVisible }) => {
  const ref = useRef(null);
  const [isInView, setIsInView] = useState(false);

  const { scrollYProgress } = useScroll({
    target: ref,
    offset: ["start end", "end start"]
  });

  // Cleaner parallax without rotation
  const y = useTransform(scrollYProgress, [0, 1], [100, -100]);
  // First slide: no fade-in (starts fully visible), Last slide: no fade-out (stays visible)
  const opacityInput = [0, 0.3, 0.7, 1];
  const opacityOutput = [noFadeIn ? 1 : 0, 1, 1, noFadeOut ? 1 : 0];
  const scaleOutput = [noFadeIn ? 1 : 0.9, 1, 1, noFadeOut ? 1 : 0.9];
  const opacity = useTransform(scrollYProgress, opacityInput, opacityOutput);
  const scale = useTransform(scrollYProgress, opacityInput, scaleOutput);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsInView(true);
          if (onVisible) onVisible();
        }
      },
      { threshold: 0.5 }
    );

    if (ref.current) {
      observer.observe(ref.current);
    }

    return () => {
      if (ref.current) {
        observer.unobserve(ref.current);
      }
    };
  }, [onVisible]);

  return (
    <div ref={ref} className="slide-section">
      <motion.div
        className="slide-content"
        style={{ 
          y,
          opacity,
          scale
        }}
        initial={{ opacity: 0, y: 50, scale: 0.95 }}
        animate={isInView ? { opacity: 1, y: 0, scale: 1 } : {}}
        transition={{ 
          duration: 0.8, 
          ease: [0.22, 1, 0.36, 1]
        }}
      >
        <img
          src={slide}
          alt={`Slide ${index + 1}`}
          className="slide-image"
        />
      </motion.div>
    </div>
  );
};

export default ScrollRevealSlides;
